class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<List<CurrencyModel>> _currenciesFuture;
  late Future<List<NewsModel>> _newsFuture;

  @override
  void initState() {
    super.initState();
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _currenciesFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD'));
    _newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeColors colors = context.colors;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currenciesFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> currenciesSnapshot) {
          if (!currenciesSnapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel> currencies = currenciesSnapshot.data!;

          return FutureBuilder<List<NewsModel>>(
            future: _newsFuture,
            builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> newsSnapshot) {
              if (!newsSnapshot.hasData) {
                return const Center(child: CircularProgressIndicator());
              }

              final List<NewsModel> news = newsSnapshot.data!;

              return Column(
                children: [
                  Expanded(
                    flex: 2,
                    child: _buildCurrenciesSection(currencies),
                  ),
                  SizedBox(height: 16),
                  Expanded(
                    flex: 3,
                    child: _buildNewsSection(news),
                  ),
                ],
              );
            },
          );
        },
      ),
    );
  }

  Widget _buildCurrenciesSection(List<CurrencyModel> currencies) {
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Container(
      margin: const EdgeInsets.fromLTRB(22, 16, 22, 0),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: colors.cardColor,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('Курсы валют', style: fonts.semiBold16),
          const SizedBox(height: 8),
          Flexible(
            child: ListView.builder(
              shrinkWrap: true,
              itemCount: currencies.length > 5 ? 5 : currencies.length,
              itemBuilder: (BuildContext context, int index) {
                final CurrencyModel model = currencies[index];
                return Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: Row(
                    children: [
                      Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(
                          color: colors.currencyCardSymbolBackground,
                          shape: BoxShape.circle,
                        ),
                        child: Center(child: Text(model.symbol, style: fonts.semiBold12.copyWith(color: Colors.white))),
                      ),
                      const SizedBox(width: 8),
                      Expanded(child: Text(model.name, style: fonts.regular14)),
                      Text(
                        '${model.nominal} ${model.value.toStringAsFixed(2)}',
                        style: fonts.semiBold14,
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildNewsSection(List<NewsModel> news) {
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Container(
      margin: const EdgeInsets.fromLTRB(22, 0, 22, 40),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: colors.cardColor,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('Новости', style: fonts.semiBold16),
          const SizedBox(height: 8),
          Flexible(
            child: ListView.builder(
              shrinkWrap: true,
              itemCount: news.length > 5 ? 5 : news.length,
              itemBuilder: (BuildContext context, int index) {
                final NewsModel model = news[index];

                return GestureDetector(
                  onTap: () => tryLaunchUrl(model.link),
                  child: Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(model.title, style: fonts.semiBold14),
                        if (model.date != null)
                          Padding(
                            padding: const EdgeInsets.only(top: 4),
                            child: Text(
                              '${formatDate(model.date!)} • cbr.ru',
                              style: fonts.regular12.copyWith(color: colors.tin),
                            ),
                          ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }

  String formatDate(DateTime date) {
    final List<String> days = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
    final List<String> months = [
      'янв.', 'фев.', 'мар.', 'апр.', 'мая', 'июн.',
      'июл.', 'авг.', 'сен.', 'окт.', 'ноя.', 'дек.'
    ];

    return '${days[date.weekday % 7]} '
        '${date.day.toString().padLeft(2, '0')}.$months[(date.month - 1) * 1].${date.year}';
  }
}
